func init() {
	for id, meta := range chezProviderRegistry {
		if _, ok := ProviderRegistry[id]; !ok {
			ProviderRegistry[id] = meta
		}
	}
	for id, cfg := range chezKnownProviders {
		if _, ok := KnownProviders[id]; !ok {
			KnownProviders[id] = cfg
		}
	}
	for id, models := range chezModels {
		if _, ok := ProviderModels[id]; !ok {
			ProviderModels[id] = models
		}
	}
	for alias, id := range chezAliasMap {
		if _, ok := ProviderAliasMap[alias]; !ok {
			ProviderAliasMap[alias] = id
		}
	}
}
